<?php
require_once 'config/auth.php'; require_payment();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['order_id']??0);$action=$_POST['action']??'';
 if($action==='receive'){$stmt=$pdo->prepare("UPDATE orders SET status='Delivered',received_at=NOW(),updated_at=NOW() WHERE id=? AND user_id=? AND status='To Receive'");$stmt->execute([$id,$_SESSION['user_id']]);flash($stmt->rowCount()?'success':'error',$stmt->rowCount()?'Order marked as delivered.':'This order is not ready to receive.');}
 if($action==='cancel'){$stmt=$pdo->prepare("UPDATE orders SET status='Cancelled',updated_at=NOW() WHERE id=? AND user_id=? AND status='Pending'");$stmt->execute([$id,$_SESSION['user_id']]);flash($stmt->rowCount()?'success':'error',$stmt->rowCount()?'Order cancelled.':'This order can no longer be cancelled.');}
 redirect('orders.php');}
$stmt=$pdo->prepare("SELECT o.* FROM orders o WHERE o.user_id=? AND o.status NOT IN ('Delivered','Cancelled') ORDER BY o.created_at DESC");$stmt->execute([$_SESSION['user_id']]);$orders=$stmt->fetchAll();
$page_title='My Purchase — PEPTIXIE';require 'config/header.php'; ?>
<div class="page-head"><div><h1>My Purchase</h1><p>Order status updates automatically while this page is open.</p></div><span class="badge"><?=count($orders)?> Active</span></div>
<?php if(!$orders): ?><div class="empty">No active purchases.</div><?php endif; ?>
<?php foreach($orders as $o): ?><div class="order-card live-order" data-order-id="<?= (int)$o['id'] ?>"><div class="order-head"><b>Order #<?=e($o['order_number'])?></b><span class="status live-status"><?=e($o['status'])?></span></div>
<p class="muted"><?=date('M d, Y h:i A',strtotime($o['created_at']))?> · <?=e($o['delivery_method'])?></p>
<div class="order-details"><b>What was ordered:</b><div class="live-items">Loading items…</div></div>
<?php if($o['tracking_number']): ?><p class="tracking"><b>J&T Tracking Number:</b> <?=e($o['tracking_number'])?></p><?php endif; ?>
<div class="timeline"><span class="done">🕐 Pending</span><span>💳 Payment Received</span><span>✅ Approved</span><span>📦 To Ship</span><span>🚚 To Receive</span><span>🎉 Delivered</span></div>
<div class="order-foot"><strong class="live-total"><?=money((float)$o['total'])?></strong><div class="order-actions"><?php if($o['status']==='Pending'): ?><a class="btn btn-outline" href="edit-order.php?id=<?=$o['id']?>">✏️ Edit Order</a><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="cancel"><button class="btn btn-outline">Cancel Order</button></form><?php endif; ?><?php if($o['status']==='To Receive'): ?><form class="inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="receive"><button class="btn">✓ Confirm Delivered</button></form><?php endif; ?></div></div></div><?php endforeach; ?>
<script>
(function(){const cards=[...document.querySelectorAll('.live-order')];if(!cards.length)return;let busy=false;function esc(s){return String(s).replace(/[<>&"']/g,'');}function update(card,d){const b=card.querySelector('.live-status');if(b)b.textContent=d.status;const t=card.querySelector('.live-total');if(t)t.textContent='₱'+Number(d.total).toLocaleString('en-PH',{minimumFractionDigits:2});const it=card.querySelector('.live-items');if(it)it.innerHTML=(d.items||[]).map(x=>esc(x.product_name)+' × '+esc(x.quantity)).join('<br>');const tr=card.querySelector('.tracking');if(d.tracking_number){if(tr)tr.innerHTML='<b>J&T Tracking Number:</b> '+esc(d.tracking_number);else card.querySelector('.order-details').insertAdjacentHTML('afterend','<p class="tracking"><b>J&T Tracking Number:</b> '+esc(d.tracking_number)+'</p>');}if(['Delivered','Cancelled'].includes(d.status)){setTimeout(()=>location.reload(),250);}}
async function refresh(){if(busy)return;busy=true;try{for(const c of cards){const r=await fetch('order-status.php?id='+c.dataset.orderId,{cache:'no-store'});if(r.ok){const d=await r.json();if(d.ok)update(c,d);}}}catch(e){}busy=false;}refresh();setInterval(refresh,1000);})();
</script><?php require 'config/footer.php'; ?>